wit_bindgen::generate!({
    world: "guest",
    path: "wit",
    generate_all,
});

// Exported interface module path generated by wit-bindgen for components.
use crate::exports::afxdp::demo::packet;

struct Component;

fn read_be_u16(b: &[u8]) -> Option<u16> {
    if b.len() < 2 {
        None
    } else {
        Some(u16::from_be_bytes([b[0], b[1]]))
    }
}

fn read_be_u32(b: &[u8]) -> Option<u32> {
    if b.len() < 4 {
        None
    } else {
        Some(u32::from_be_bytes([b[0], b[1], b[2], b[3]]))
    }
}

fn mac_to_string(mac: &[u8]) -> String {
    mac.iter()
        .map(|b| format!("{b:02x}"))
        .collect::<Vec<_>>()
        .join(":")
}

fn ipv4_to_string(ip: &[u8]) -> String {
    format!("{}.{}.{}.{}", ip[0], ip[1], ip[2], ip[3])
}

/// Very small demo parser:
/// Ethernet(14) -> optionally VLAN(4) -> IPv4 -> TCP -> HTTP (prefix scan)
fn parse_and_print(frame: &[u8]) {
    if frame.len() < 14 {
        return;
    }

    let dst = &frame[0..6];
    let src = &frame[6..12];
    let mut ethertype = read_be_u16(&frame[12..14]).unwrap_or(0);
    let mut offset = 14usize;

    // VLAN 802.1Q
    if ethertype == 0x8100 && frame.len() >= 18 {
        ethertype = read_be_u16(&frame[16..18]).unwrap_or(0);
        offset += 4;
    }

    if ethertype != 0x0800 {
        // Not IPv4
        return;
    }

    if frame.len() < offset + 20 {
        return;
    }

    let ihl = (frame[offset] & 0x0f) as usize * 4;
    if ihl < 20 || frame.len() < offset + ihl {
        return;
    }

    let proto = frame[offset + 9];
    let src_ip = &frame[offset + 12..offset + 16];
    let dst_ip = &frame[offset + 16..offset + 20];
    offset += ihl;

    if proto != 6 {
        // not TCP
        return;
    }

    if frame.len() < offset + 20 {
        return;
    }

    let src_port = read_be_u16(&frame[offset..offset + 2]).unwrap_or(0);
    let dst_port = read_be_u16(&frame[offset + 2..offset + 4]).unwrap_or(0);
    let data_off = ((frame[offset + 12] >> 4) as usize) * 4;
    if data_off < 20 || frame.len() < offset + data_off {
        return;
    }
    offset += data_off;

    // HTTP heuristic: method prefix
    let payload = &frame[offset..];
    let http = payload
        .strip_prefix(b"GET ")
        .or_else(|| payload.strip_prefix(b"POST "))
        .or_else(|| payload.strip_prefix(b"PUT "))
        .or_else(|| payload.strip_prefix(b"HEAD "))
        .or_else(|| payload.strip_prefix(b"HTTP/"));

    println!(
        "L2 {} -> {} | L3 {}:{} -> {}:{} | eth=0x{:04x} | http={} ",
        mac_to_string(src),
        mac_to_string(dst),
        ipv4_to_string(src_ip),
        src_port,
        ipv4_to_string(dst_ip),
        dst_port,
        ethertype,
        http.is_some(),
    );
}

impl Guest for Component {
    fn run() {
        println!("afxdp-guest: run()");
    }
}

impl packet::Guest for Component {
    fn on_packet(meta: packet::PacketMeta, data: Vec<u8>) {
        // Keep output lightweight: print the first packet, then only periodic summaries.
        // (For now we just parse and print on every call; you can throttle later.)
        println!(
            "afxdp-guest: on_packet(frame_len={}, rx_queue={}, data_len={})",
            meta.frame_len,
            meta.rx_queue,
            data.len()
        );

        // Optional tiny dissector (best-effort; safe on short buffers)
        parse_and_print(&data);
    }
}

export!(Component);
